      for (let k = 1; k < N; k++) { const mx = (P[k].x + P[k + 1].x) / 2, my = (P[k].y + P[k + 1].y) / 2; d += ` Q${P[k].x.toFixed(1)},${P[k].y.toFixed(1)} ${mx.toFixed(1)},${my.toFixed(1)}`; }
